import "server-only";
import { db } from "@/lib/db";
import { countQuotaUsage } from "@/lib/delivery-usage";
import {
  historicalUsagePeriods,
  resolveUsagePeriods,
  UsagePeriodError,
} from "@/lib/usage-periods";
import {
  adoptUsageReservation,
  ensureUsagePeriods,
  importUsageEvidence,
  repairUsageCounters,
  settleUsageReceipt,
  USAGE_BACKFILL_VERSION,
  withUsageTransaction,
  type UsageOwnerTransaction,
} from "@/lib/usage-ledger";

/** Durable acceptance wins over stale worker state. History deletion and the
 * reconciler call the same primitive before discarding successful Send rows. */
export async function preserveAcceptedSend(
  owner: UsageOwnerTransaction,
  sendId: string,
) {
  const { tx, userId } = owner;
  const send = await tx.send.findFirstOrThrow({
    where: { id: sendId, campaign: { userId } },
  });
  if (
    !send.sentAt ||
    (!["SENT", "REPLIED"].includes(send.status) && !send.gmailMessageId)
  )
    throw new Error("Durable acceptance evidence required.");
  const reservation = await tx.usageReservation.findFirst({
    where: { userId, sendId },
  });
  const user = await tx.user.findUniqueOrThrow({ where: { id: userId } });
  const chargedAt = reservation?.chargedAt ?? send.attemptedAt ?? send.sentAt;
  if (reservation) {
    await adoptUsageReservation(owner, {
      sendId,
      deliveryKey: reservation.deliveryKey,
      specs: historicalUsagePeriods(user, chargedAt),
      status: "CONFIRMED",
      chargedAt,
      confirmedAt: send.sentAt,
    });
  } else {
    const existing = await tx.usageImportEvidence.findFirst({
      where: { userId, deliveryKey: send.id },
    });
    if (!existing)
      await importUsageEvidence(owner, {
        sourceKey: `delivery:${send.id}`,
        deliveryKey: send.id,
        chargedAt,
        timestampSource: send.attemptedAt ? "attemptedAt" : "sentAt",
      });
  }
  if (
    !["SENT", "REPLIED"].includes(send.status) ||
    send.deliveryState !== "DONE"
  )
    await tx.send.updateMany({
      where: { id: sendId, campaign: { userId } },
      data: {
        status: "SENT",
        deliveryState: "DONE",
        claimToken: null,
        leaseExpiresAt: null,
        error: null,
      },
    });
  return reservation?.deliveryKey ?? send.id;
}

/** Independent SQL reconstruction, deliberately separate from counter updates. */
async function validateUsageOwner(owner: UsageOwnerTransaction) {
  const { tx, userId } = owner;
  const expected = await tx.$queryRaw<
    {
      id: string;
      sent: number;
      reserved: number;
      importedSent: number;
      importedReserved: number;
    }[]
  >`
    SELECT p.id,
      (SELECT count(*)::int FROM "UsageReservation" r WHERE r."userId"=${userId} AND r.status='CONFIRMED'
        AND ((p.kind='DAILY' AND r."dailyPeriodId"=p.id) OR (p.kind='MONTHLY' AND r."monthlyPeriodId"=p.id)
          OR (r."chargedAt">=p."startsAt" AND r."chargedAt"<p."operationalEndsAt")))
      + (SELECT count(*)::int FROM "UsageImportEvidence" e WHERE e."userId"=${userId}
        AND e."chargedAt">=p."startsAt" AND e."chargedAt"<p."operationalEndsAt"
        AND NOT EXISTS (SELECT 1 FROM "UsageReservation" r WHERE r."userId"=${userId} AND r."deliveryKey"=e."deliveryKey")) AS sent,
      (SELECT count(*)::int FROM "UsageReservation" r WHERE r."userId"=${userId} AND r.status IN ('RESERVED','ATTEMPTING','UNCERTAIN')
        AND ((p.kind='DAILY' AND r."dailyPeriodId"=p.id) OR (p.kind='MONTHLY' AND r."monthlyPeriodId"=p.id)
          OR (r."chargedAt">=p."startsAt" AND r."chargedAt"<p."operationalEndsAt"))) AS reserved,
      (SELECT count(*)::int FROM "UsageReservation" r WHERE r."userId"=${userId} AND r.status='CONFIRMED'
        AND (CASE WHEN p.kind='DAILY' THEN r."dailyPeriodId" ELSE r."monthlyPeriodId" END)<>p.id
        AND r."chargedAt">=p."startsAt" AND r."chargedAt"<p."operationalEndsAt")
      + (SELECT count(*)::int FROM "UsageImportEvidence" e WHERE e."userId"=${userId}
        AND e."chargedAt">=p."startsAt" AND e."chargedAt"<p."operationalEndsAt"
        AND NOT EXISTS (SELECT 1 FROM "UsageReservation" r WHERE r."userId"=${userId} AND r."deliveryKey"=e."deliveryKey")) AS "importedSent",
      (SELECT count(*)::int FROM "UsageReservation" r WHERE r."userId"=${userId} AND r.status IN ('RESERVED','ATTEMPTING','UNCERTAIN')
        AND (CASE WHEN p.kind='DAILY' THEN r."dailyPeriodId" ELSE r."monthlyPeriodId" END)<>p.id
        AND r."chargedAt">=p."startsAt" AND r."chargedAt"<p."operationalEndsAt") AS "importedReserved"
    FROM "UsagePeriod" p WHERE p."userId"=${userId}`;
  const actual = await tx.usagePeriod.findMany({ where: { userId } });
  for (const row of expected) {
    const period = actual.find((p) => p.id === row.id)!;
    for (const key of [
      "sent",
      "reserved",
      "importedSent",
      "importedReserved",
    ] as const)
      if (row[key] !== period[key])
        throw new Error("Usage period validation failed.");
  }
  const missing = await tx.$queryRaw<{ id: string }[]>`
    SELECT s.id FROM "Send" s JOIN "Campaign" c ON c.id=s."campaignId" WHERE c."userId"=${userId}
    AND (s.status IN ('QUEUED','SENT','REPLIED') OR s."deliveryState" IN ('ATTEMPTING','UNCERTAIN'))
    AND NOT EXISTS (SELECT 1 FROM "UsageReservation" r WHERE r."userId"=${userId} AND r."sendId"=s.id)
    AND NOT EXISTS (SELECT 1 FROM "UsageImportEvidence" e WHERE e."userId"=${userId} AND e."deliveryKey"=s.id)
    UNION ALL
    SELECT d.id FROM "DeliveryReceipt" d WHERE d."userId"=${userId}
    AND NOT EXISTS (SELECT 1 FROM "UsageReservation" r WHERE r."userId"=${userId} AND r."deliveryKey"=d."deliveryKey")
    AND NOT EXISTS (SELECT 1 FROM "UsageImportEvidence" e WHERE e."userId"=${userId} AND e."deliveryKey"=d."deliveryKey")`;
  if (missing.length) throw new Error("Usage evidence validation failed.");
  return {
    periods: expected.length,
    legacyRollingUsed: await countQuotaUsage(userId, tx),
  };
}

export async function backfillUsageOwner(
  userId: string,
  cutover: Date,
  apply = false,
) {
  const dryRun = Symbol("dry-run");
  let result:
    | {
        ready: boolean;
        sends: number;
        receipts: number;
        periods: number;
        legacyRollingUsed: number;
      }
    | undefined;
  try {
    await withUsageTransaction(db, userId, async (owner) => {
      const { tx } = owner;
      if (apply) {
        const control = await tx.systemControl.findUniqueOrThrow({
          where: { key: "global" },
        });
        if (control.sendingEnabled)
          throw new Error("Pause sending before applying usage backfill.");
      }
      const user = await tx.user.findUniqueOrThrow({ where: { id: userId } });
      const originalCutover = user.usageCutoverAt ?? cutover;
      const sends = await tx.send.findMany({
        where: { campaign: { userId } },
        orderBy: { id: "asc" },
      });
      for (const send of sends) {
        if (
          send.sentAt &&
          (["SENT", "REPLIED"].includes(send.status) || send.gmailMessageId)
        ) {
          await preserveAcceptedSend(owner, send.id);
          continue;
        }
        if (
          send.status !== "QUEUED" &&
          !["ATTEMPTING", "UNCERTAIN"].includes(send.deliveryState)
        )
          continue;
        const uncertain =
          send.deliveryState !== "READY" || send.attemptedAt !== null;
        const at = uncertain
          ? (send.attemptedAt ?? send.createdAt)
          : originalCutover;
        await adoptUsageReservation(owner, {
          sendId: send.id,
          deliveryKey: send.id,
          specs: historicalUsagePeriods(user, at),
          status: uncertain ? "UNCERTAIN" : "RESERVED",
          chargedAt: uncertain ? at : null,
        });
        if (!uncertain && !send.queueExpiresAt)
          await tx.send.updateMany({
            where: { id: send.id, campaign: { userId }, queueExpiresAt: null },
            data: {
              queueExpiresAt: new Date(+originalCutover + 86400000),
              availableAt: send.availableAt ?? originalCutover,
            },
          });
      }
      const receipts = await tx.deliveryReceipt.findMany({ where: { userId } });
      for (const receipt of receipts) {
        const key = receipt.deliveryKey ?? receipt.id;
        const [ledger, evidence] = await Promise.all([
          tx.usageReservation.findFirst({
            where: { userId, deliveryKey: key },
          }),
          tx.usageImportEvidence.findFirst({
            where: { userId, deliveryKey: key },
          }),
        ]);
        if (ledger && ledger.status !== "CONFIRMED")
          await settleUsageReceipt(
            owner,
            receipt.id,
            historicalUsagePeriods(user, ledger.chargedAt ?? receipt.sentAt),
          );
        if (!ledger && !evidence)
          await importUsageEvidence(owner, {
            sourceKey: `delivery:${key}`,
            deliveryKey: key,
            chargedAt: receipt.sentAt,
            timestampSource: "sentAt",
          });
        if (!receipt.deliveryKey)
          await tx.deliveryReceipt.updateMany({
            where: { id: receipt.id, userId },
            data: { deliveryKey: key },
          });
      }
      // Even a paused billing boundary needs historical accounting. It does not
      // authorize sending; current-period resolution will continue to fail closed.
      try {
        await ensureUsagePeriods(
          owner,
          resolveUsagePeriods(user, originalCutover),
        );
      } catch (error) {
        if (!(error instanceof UsagePeriodError)) throw error;
        await ensureUsagePeriods(
          owner,
          historicalUsagePeriods(user, originalCutover),
        );
      }
      await repairUsageCounters(owner);
      const validation = await validateUsageOwner(owner);
      await tx.user.update({
        where: { id: userId },
        data: {
          usageBackfillVersion: USAGE_BACKFILL_VERSION,
          usageCutoverAt: originalCutover,
        },
      });
      result = {
        ready: true,
        sends: sends.length,
        receipts: receipts.length,
        ...validation,
      };
      if (!apply) throw dryRun;
    });
  } catch (error) {
    if (error !== dryRun) throw error;
  }
  return result!;
}
